candidates.pseudocode:
// research: which entry-filter primitives count as a 'reason' is a design decision left to the authoring pass
reasonsTrue = countTrue([reasonA[0], reasonB[0], reasonC[0], /* ... enumerable list of sibling Entry filters */]);
allowEntry = reasonsTrue >= reasonCount || singleReasonExceptionApplies[0];

// hard: needs to remember whether a same-direction setup recently failed/quickly reversed
firstAttemptFailedRecently = hadRecentSameDirectionFailedSetup(withinBars = secondEntryWindow);
isSecondEntry = firstAttemptFailedRecently && isSameDirectionSetup[0];

// hard: requires trend-line/channel-line projection from pivots for two independent lines
lineAValue = trendLineValue(lineA, currentBarIndex);
lineBValue = trendLineValue(lineB, currentBarIndex);
isDuelingLinesZone = abs(lineAValue - lineBValue) <= duelingLinesTolerance;

// research: 'expected profit target' is context-dependent (scalp target, measured move, etc.)
referenceExtreme = recentSignalBarExtreme[0];
failedToExtendPastTarget = maxFavorableExcursionSince(referenceExtreme, lookbackBars = failureLookback) < failureTicks * tickSize
   && close[0] < referenceExtreme; // gave the level back
reasonPresent = failedToExtendPastTarget;

// moderate: needs a persistent counter of MA-gap pullbacks since the trend began
isMovingAverageGapPullback = isPullbackInTrend[0] && !touchedMovingAverage[0];
isFirstOfTrend = movingAverageGapPullbackCountSinceTrendStart == 0;
reasonPresent = isMovingAverageGapPullback && isFirstOfTrend;

// research: 'tight trading range' needs a range-tightness definition
largeBarBreakoutFailed = wasLargeTrendBarBreakout(ticksBeyondRange = breakoutTicks, atBar = k) && closedBackInsideRangeWithinBars(k, failFollowThroughBars);
smallBarAtExtreme = isSmallBar[0] && isNearRangeExtreme[0];
allowEntry = !isTightTradingRange[0] || largeBarBreakoutFailed || smallBarAtExtreme;

priorSwingLowPrice = mostRecentSwingLow[0].price;
isValidLongLimitEntry = low[1] > priorSwingLowPrice && low[0] <= priorSwingLowPrice;
enterHalfSizeLongAtLimit = isValidLongLimitEntry;

firstEntryPrice = ctx.EntryPrice(); // the R26-14 fill
addOnLimitPrice = firstEntryPrice - addOnDistance;
isValidAddOnFill = low[1] > addOnLimitPrice && low[0] <= addOnLimitPrice;
enterSecondHalfLongAtLimit = isValidAddOnFill;

onlyFirstEntryFilled = ctx.MarketPosition() == 1 && positionSize == firstEntrySize; // add-on has not yet filled
targetPrice = ctx.EntryPrice() + profitTargetPoints;
exitLongAtTarget = onlyFirstEntryFilled && high[0] >= targetPrice;

bothEntriesFilled = ctx.MarketPosition() == 1 && positionSize == fullPositionSize;
originalEntryPrice = firstScaleInFillPrice; // the R26-14 fill, not the average entry
exitEntirePositionAtOriginalEntry = bothEntriesFilled && high[0] >= originalEntryPrice;
